// yes, the data bits are checked for this specific value
	if (data == 0x39)
		m_watchdog->watchdog_reset();

// yes, the data bits are checked for this specific value
	if ((data & 0x3f) == 0x14)
		m_watchdog->watchdog_reset();

// Mayday does some kind of protection check that is not currently understood
	// However, the results of that protection check are stored at $a190 and $a191
	// These are compared against $a193 and $a194, respectively. Thus, to prevent
	// the protection from resetting the machine, we just return $a193 for $a190,
	// and $a194 for $a191.
	return m_videoram[0xa193 + offset];

// VRAM/ROM banking from bit 0
	if (BIT(data, 0))
		m_rom_view.select(0);
	else
		m_rom_view.disable();

	// cocktail flip from bit 1
	m_cocktail = BIT(data, 1);

// yes, the data bits are checked for this specific value
	if (data == 0x39)
		m_watchdog->watchdog_reset();

// low two bits are standard
	vram_select_w(data);

	// window enable from bit 2 (clips to 0x7400)
	m_blitter->window_enable_w(BIT(data, 2));

// VRAM/ROM banking from bit 0
	if (BIT(data, 0))
		m_rom_view.select(0);
	else
		m_rom_view.disable();

	// cocktail flip from bit 1
	m_cocktail = BIT(data, 1);

	// window enable from bit 2 (clips to 0x9700)
	m_blitter->window_enable_w(BIT(data, 2));

m_remap_index = data;
	if (m_proms != nullptr)
		m_remap = m_remap_lookup.get() + data * 256;

// yes, the data bits are checked for this specific value
	if (data == 0x39)
		m_watchdog->watchdog_reset();

// set the new value
	m_paletteram[offset] = data;

	// pull the associated low/high bytes
	uint16_t entry_lo = m_paletteram[offset & ~1];
	uint16_t entry_hi = m_paletteram[offset |  1];

	m_bg_tilemap->mark_all_dirty();

	m_palette->set_pen_color(offset / 2, calc_col(entry_lo, entry_hi));

// the low two bits control the paging
	switch (data & 0x03)
	{
		// page 0 is video ram
		case 0:
			m_rom_view.disable();
			m_palette_view.disable();
			break;

		// pages 1 and 2 are ROM
		case 1:
		case 2:
			m_mainbank->set_entry((data & 6) >> 1);
			m_rom_view.select(0);
			m_palette_view.disable();
			break;

		// page 3 accesses palette RAM; the remaining areas are as if page 1 ROM was selected
		case 3:
			m_mainbank->set_entry((data & 4) >> 1);
			m_rom_view.select(0);
			m_palette_view.select(0);
			break;
	}

int n;
	char dot;

	switch (data & 0x7F)
	{
		case 0x40:  n = 0; break;
		case 0x79:  n = 1; break;
		case 0x24:  n = 2; break;
		case 0x30:  n = 3; break;
		case 0x19:  n = 4; break;
		case 0x12:  n = 5; break;
		case 0x02:  n = 6; break;
		case 0x03:  n = 6; break;
		case 0x78:  n = 7; break;
		case 0x00:  n = 8; break;
		case 0x18:  n = 9; break;
		case 0x10:  n = 9; break;
		default:    n =-1; break;
	}

	if ((data & 0x80) == 0x00)
		dot = '.';
	else
		dot = ' ';

	if (n == -1)
		logerror("[ %c]\n", dot);
	else
		logerror("[%d%c]\n", n, dot);

// IC79 is a 74LS85 comparator that controls the low bit
	m_bg_color = data;
	m_bg_tilemap->mark_all_dirty();

m_cpu->set_input_line(M6809_IRQ_LINE, CLEAR_LINE);

	// don't clear the external IRQ state for a short while; this allows the
	// self-tests to pass
	m_irq_clear_timer->adjust(attotime::from_usec(10));
	return m_latch;

m_control = data;
	m_no_even = BIT(data, CONTROLBYTE_NO_EVEN);
	m_no_odd = BIT(data, CONTROLBYTE_NO_ODD);
	m_solid = BIT(data, CONTROLBYTE_SOLID);
	m_fg_only = BIT(data, CONTROLBYTE_FOREGROUND_ONLY);

	int w = m_width ^ m_size_xor;
	int h = m_height ^ m_size_xor;

	if (w == 0)
		w = 1;
	if (h == 0)
		h = 1;

	const int accesses = blit_core(space, w, h);

	// based on the number of memory accesses needed to do the blit, compute how long the blit will take
	int estimated_clocks_at_4MHz = 4;
	if (BIT(m_control, CONTROLBYTE_SLOW))
		estimated_clocks_at_4MHz += 4 * (accesses + 2);
	else
		estimated_clocks_at_4MHz += 2 * (accesses + 3);

	m_cpu->adjust_icount(-((estimated_clocks_at_4MHz + 3) / 4));

	// log blits
	LOG("%04X:Blit : %04X -> %04X, %3dx%3d, mask=%02X, flags=%02X, icount=%d, win=%d\n",
		m_cpu->pc(), m_sstart, m_dstart, m_width, m_height, m_solid_color, m_control,
		((estimated_clocks_at_4MHz + 3) / 4), m_window_enable);

// compute how much to advance in the x and y loops
	const bool dst_stride_256 = BIT(m_control, CONTROLBYTE_DST_STRIDE_256);
	const bool src_stride_256 = BIT(m_control, CONTROLBYTE_SRC_STRIDE_256);
	const int sxadv = src_stride_256 ? 0x100 : 1;
	const int syadv = src_stride_256 ? 1 : w;
	const int dxadv = dst_stride_256 ? 0x100 : 1;
	const int dyadv = dst_stride_256 ? 1 : w;

	int accesses = 0;
	int pixdata = 0;

	// loop over the height
	const bool shift = BIT(m_control, CONTROLBYTE_SHIFT);
	u16 sstart = m_sstart;
	u16 dstart = m_dstart;
	for (int y = 0; y < h; y++)
	{
		u16 source = sstart;
		u16 dest = dstart;

		// loop over the width
		for (int x = 0; x < w; x++)
		{
			const u8 rawval = m_remap[space.read_byte(source)];
			if (shift)
			{
				// shift one pixel right
				pixdata = (pixdata << 8) | rawval;
				blit_pixel(space, dest, (pixdata >> 4) & 0xff);
			}
			else
			{
				blit_pixel(space, dest, rawval);
			}
			accesses += 2;

			// advance src and dst pointers
			source += sxadv;
			dest   += dxadv;
		}

		// note that PlayBall! indicates the X coordinate doesn't wrap
		if (dst_stride_256)
			dstart = (dstart & 0xff00) | ((dstart + dyadv) & 0xff);
		else
			dstart += dyadv;

		if (src_stride_256)
			sstart = (sstart & 0xff00) | ((sstart + syadv) & 0xff);
		else
			sstart += syadv;
	}
	return accesses;

// always read from video RAM regardless of the bank setting
	int curpix = (dstaddr < 0xc000) ? m_vram[dstaddr] : space.read_byte(dstaddr); // current pixel values at dest

	u8 keepmask = 0xff; // what part of original dst byte should be kept, based on NO_EVEN and NO_ODD flags

	// even pixel (D7-D4)
	if (m_fg_only && !(srcdata & 0xf0)) // FG only and src even pixel=0
	{
		if (m_no_even)
			keepmask &= 0x0f;
	}
	else
	{
		if (!m_no_even)
			keepmask &= 0x0f;
	}

	// odd pixel (D3-D0)
	if (m_fg_only && !(srcdata & 0x0f)) // FG only and src odd pixel=0
	{
		if (m_no_odd)
			keepmask &= 0xf0;
	}
	else
	{
		if (!m_no_odd)
			keepmask &= 0xf0;
	}

	curpix &= keepmask;
	if (m_solid)
		curpix |= m_solid_color & ~keepmask;
	else
		curpix |= srcdata & ~keepmask;

	/* if the window is enabled, only blit to videoram below the clipping address */
	/* note that we have to allow blits to non-video RAM (e.g. tileram, Sinistar $DXXX SRAM) because those */
	/* are not blocked by the window enable */
	if (!m_window_enable || dstaddr < m_clip_address || dstaddr >= 0xc000)
		space.write_byte(dstaddr, curpix);

williams_state::machine_reset();

	// make sure our banking is reset
	bank_select_w(0);

williams_state::video_start();

	// create the tilemap
	m_bg_tilemap = &machine().tilemap().create(*m_gfxdecode, tilemap_get_info_delegate(*this, FUNC(williams2_state::get_tile_info)), TILEMAP_SCAN_COLS, 24,16, 128,16);
	m_bg_tilemap->set_scrolldx(2, 0);

	save_item(NAME(m_tilemap_xscroll));
	save_item(NAME(m_fg_color));
	save_item(NAME(m_gain));
	save_item(NAME(m_offset));

int const mask = m_gfxdecode->gfx(0)->elements() - 1;
	int const data = m_tileram[tile_index];
	int const y = (tile_index >> 1) & 7;

	// On tshoot and inferno, IC79 is a 74LS157 selector jumpered to be enabled
	int const color = y;

	tileinfo.set(0, data & mask, color, (data & ~mask) ? TILE_FLIPX : 0);

int const color = color_decode(m_bg_color, 0, (tile_index << 4) & 0xff);

	int const mask = m_gfxdecode->gfx(0)->elements() - 1;
	int const data = m_tileram[tile_index];

	//m_bg_tilemap->set_palette_offset((color & 0x3e) << 4);
	//tileinfo.set(0, data & mask, color & 1, (data & ~mask) ? TILE_FLIPX : 0);
	m_bg_tilemap->set_palette_offset(0);
	tileinfo.set(0, data & mask, (color & 0x3f), (data & ~mask) ? TILE_FLIPX : 0);

	//gfx_element *gfx = tileinfo.decoder->gfx(0);
	//printf("%d %d %d %d\n", gfx->elements(), gfx->colorbase(), gfx->granularity(), gfx->colors());

int const v = y << 6;
	int const sig_W11 = (v >> 11) & 1;
	int const sig_W12 = (v >> 12) & 1;
	int const sig_W13 = (v >> 13) & 1;

	// There are four "jumpers" in the schematics.
	// J3 and J4 allow to turn off background tilemaps completely.
	// BACKSEL (active low) in this case is forced to high.
	// J1 and J2 allow to turn on/off "sky" processing. In this case,
	// for sky (up to ~1/3 of vertical resolution an alternative palette
	// is used. For mysticm it is connected to BACKSEL.

	// Cascading inputs ">" and "=" are set to "H", thus
	// cascading input "<" (connected to W11) has no effect
	// according to truthtable for 7485. Thus there are two possibilities:
	// a. A real 7485 works different to the datasheet
	// b. input "=" on the real board is connected to GND.

	// FIXME: Investigate further.

	// IC79 is a 74LS85 comparator that controls the low bit
	int const a = 1 | ((base_col & 1) << 2) | ((base_col & 1) << 3);
	int const b = (sig_W12 << 0) | (sig_W13 << 1) | (0 << 2) | (sig_J1 << 3);
	int const color = (a > b) || ((a == b) && !sig_W11);

	// mysticm schematics show Page1 and Page2 crossed, i.e.
	// Page1 -> B2 (IC80) and Page2 -> B1 (IC80)
	// This does not produce colors observed on real hardware.
	// FIXME: Verify Page1 and Page2 connections.
	//return ((base_col & 0x04) >> 1) | ((base_col & 0x02) << 1) | (base_col & 0x38) | color;
	return (base_col & 0x3e) | color;

int const mask = m_gfxdecode->gfx(0)->elements() - 1;
	int const data = m_tileram[tile_index];

	// IC79 is a 74LS157 selector jumpered to be disabled
	int const color = 0;

	tileinfo.set(0, data & mask, color, (data & ~mask) ? TILE_FLIPX : 0);

int const scanline = param;

	// must not fire at line 256
	if (scanline == 256)
		return;

	// the IRQ signal comes into CB1, and is set to VA11
	m_pia[1]->cb1_w(BIT(scanline, 5));

int const scanline = param;
	if (scanline == 256)
		return;

	// the IRQ signal comes into CB1, and is set to VA11
	m_pia[0]->cb1_w(BIT(scanline, 5));
	m_pia[1]->ca1_w(BIT(scanline, 5));

int const scanline = param;

	// the COUNT240 signal comes into CA1, and is set to the logical AND of VA10-VA13
	m_pia[1]->ca1_w(scanline >= 240 ? 1 : 0);

// precompute the palette
	rgb_t pens[16];
	for (int x = 0; x < 16; x++)
		pens[x] = m_palette->pen_color(m_paletteram[x]);

	// loop over rows
	for (int y = cliprect.min_y; y <= cliprect.max_y; y++)
	{
		uint8_t const *const source = &m_videoram[y];
		uint32_t *const dest = &bitmap.pix(y);

		// loop over columns
		for (int x = cliprect.min_x & ~1; x <= cliprect.max_x; x += 2)
		{
			uint8_t const pix = source[(x / 2) * 256];
			dest[x + 0] = pens[pix >> 4];
			dest[x + 1] = pens[pix & 0x0f];
		}
	}
	return 0;

uint8_t const *const palette_0 = &m_videoram[0xbb00];
	uint8_t const *const scanline_control = &m_videoram[0xbc00];
	rgb_t pens[16];

	// precompute the palette
	for (int x = 0; x < 16; x++)
		pens[x] = m_palette->pen_color(m_paletteram[x]);

	// if we're blitting from the top, start with a 0 for color 0
	if (cliprect.min_y == screen.visible_area().min_y || !(m_video_control & 1))
		m_color0 = m_palette->pen_color(palette_0[0] ^ 0xff);

	// loop over rows
	for (int y = cliprect.min_y; y <= cliprect.max_y; y++)
	{
		int const erase_behind = m_video_control & scanline_control[y] & 2;
		uint8_t *const source = &m_videoram[y];
		uint32_t *const dest = &bitmap.pix(y);

		// latch a new color0 pen?
		if (m_video_control & scanline_control[y] & 1)
			m_color0 = m_palette->pen_color(palette_0[y] ^ 0xff);

		// loop over columns
		for (int x = cliprect.min_x & ~1; x <= cliprect.max_x; x += 2)
		{
			uint8_t const pix = source[(x/2) * 256];

			// clear behind us if requested
			if (erase_behind)
				source[(x/2) * 256] = 0;

			// now draw
			dest[x+0] = (pix & 0xf0) ? pens[pix >> 4] : rgb_t(m_color0 | pens[0]);
			dest[x+1] = (pix & 0x0f) ? pens[pix & 0x0f] : rgb_t(m_color0 | pens[0]);
		}
	}
	return 0;

rgb_t pens[16];

	// draw the background
	m_bg_tilemap->draw(screen, bitmap, cliprect, 0, 0);

	// fetch the relevant pens
	for (int x = 1; x < 16; x++)
		pens[x] = m_palette->pen_color(m_fg_color * 16 + x);

	// loop over rows
	for (int y = cliprect.min_y; y <= cliprect.max_y; y++)
	{
		uint8_t const *const source = &m_videoram[y];
		uint32_t *const dest = &bitmap.pix(y);

		// loop over columns
		for (int x = cliprect.min_x & ~1; x <= cliprect.max_x; x += 2)
		{
			uint8_t const pix = source[(x/2) * 256];

			if (pix & 0xf0)
				dest[x+0] = pens[pix >> 4];
			if (pix & 0x0f)
				dest[x+1] = pens[pix & 0x0f];
		}
	}
	return 0;

rgb_t pens[16];

	// draw the background
	m_bg_tilemap->mark_all_dirty();
	m_bg_tilemap->draw(screen, bitmap, cliprect, TILEMAP_DRAW_OPAQUE | TILEMAP_DRAW_ALL_CATEGORIES, 0);

	// loop over rows
	for (int y = cliprect.min_y; y <= cliprect.max_y; y++)
	{
		// fetch the relevant pens
		for (int x = 1; x < 16; x++)
			pens[x] = m_palette->pen_color(color_decode(m_fg_color, 1, y) * 16 + x);

		uint8_t const *const source = &m_videoram[y];
		uint32_t *const dest = &bitmap.pix(y);

		// loop over columns
		for (int x = cliprect.min_x & ~1; x <= cliprect.max_x; x += 2)
		{
			uint8_t const pix = source[(x/2) * 256];

			if (pix & 0xf0)
				dest[x+0] = pens[pix >> 4];
			if (pix & 0x0f)
				dest[x+1] = pens[pix & 0x0f];
		}
	}
	return 0;

u8 const l_data = param | 0x80;
	u8 const r_data = (param >> 1 & 0x40) | (param & 0x3f) | 0x80;

	m_pia[2]->portb_w(l_data); m_pia[2]->cb1_w((l_data == 0xff) ? 0 : 1);
	m_pia[3]->portb_w(r_data); m_pia[3]->cb1_w((r_data == 0xff) ? 0 : 1);

int const scanline = param;

	// the /ENDSCREEN signal comes into CA1
	m_pia[0]->ca1_w(scanline >= 254 ? 0 : 1);

m_grenade_lamp   = BIT(~data, 2);
	m_gun_lamp       = BIT(~data, 3);
	m_p1_gun_recoil  = BIT(data, 4);
	m_feather_blower = BIT(data, 5);

if ((m_old_resetq_state != CLEAR_LINE) && (state == CLEAR_LINE))
	{
		logerror("S11 bg device received reset request\n");
		common_reset();
	}
	m_old_resetq_state = state;

m_cpubank->set_entry(0);
	// reset the CPU again, so that the CPU are starting with the right vectors (otherwise sound may die on reset)
	m_cpu->pulse_input_line(INPUT_LINE_RESET, attotime::zero);

if (!m_pb_cb.isunset())
		m_pb_cb(param);
	else
		logerror("S11C_BG PB writeback called with state 0x%2X, but callback is not registered!\n", param);

if (!m_cb2_cb.isunset())
		m_cb2_cb(param);
	else
		logerror("S11C_BG CB2 writeback called with state %x, but callback is not registered!\n", param);

// compute palette information
	// note that there really are pullup/pulldown resistors, but this situation is complicated
	// by the use of transistors, so we ignore that and just use the relative resistor weights
	double weights_r[3], weights_g[3], weights_b[2];
	compute_resistor_weights(0, 255, -1.0,
			3, resistances_rg, weights_r, 0, 0,
			3, resistances_rg, weights_g, 0, 0,
			2, resistances_b,  weights_b, 0, 0);

	// build a palette lookup
	for (int i = 0; i < 256; i++)
	{
		int const r = combine_weights(weights_r, BIT(i, 0), BIT(i, 1), BIT(i, 2));
		int const g = combine_weights(weights_g, BIT(i, 3), BIT(i, 4), BIT(i, 5));
		int const b = combine_weights(weights_b, BIT(i, 6), BIT(i, 7));

		palette.set_pen_color(i, rgb_t(r, g, b));
	}
